async function createNota(rolId: string, contenido: string) {
  const body = NotaCreateSchema.parse({ contenido })

  return fetcher(
    `/api/roles/${rolId}/notas`,
    NotaItemSchema,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    }
  )
}

